    if ((m = source.match(/^(\d+) mapped · ([\d.]+) \/ 10k seniors$/))) return `${m[1]} ${t("mapped",{},lang)} · ${m[2]} / 10k ${t("seniors",{},lang)}`;
    if ((m = source.match(/^(\d+) eldercare points?$/))) return `${m[1]} ${t("Eldercare points",{},lang)}`;
    if ((m = source.match(/^([\d.]+°C) · (.+) seniors$/))) return `${m[1]} · ${m[2]} ${t("seniors",{},lang)}`;
